[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$BackupDirectory,[switch]$ConfirmRestore,[switch]$SkipSafetyBackup,[switch]$AllowCrossRevisionRestore,[switch]$DisableAutomaticRollback,
 [string]$ArtifactDirectory='artifacts\durable',[string]$Database=$(if($env:POSTGRES_DB){$env:POSTGRES_DB}else{'dip'}),[string]$DatabaseUser=$(if($env:POSTGRES_USER){$env:POSTGRES_USER}else{'dip'}),[string]$DatabaseHost=$(if($env:POSTGRES_HOST){$env:POSTGRES_HOST}else{'127.0.0.1'}),[int]$DatabasePort=$(if($env:POSTGRES_PORT){[int]$env:POSTGRES_PORT}else{5432}),[string]$DatabasePassword=$(if($env:POSTGRES_PASSWORD){$env:POSTGRES_PASSWORD}else{''}))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(-not$ConfirmRestore){throw 'Restore is destructive. Re-run with -ConfirmRestore.'};foreach($n in 'pg_restore','psql','git'){if(-not(Get-Command $n -ErrorAction SilentlyContinue)){throw "$n is required."}}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$backup=(Resolve-Path $BackupDirectory).Path;$dump=Join-Path $backup 'database.dump';$zip=Join-Path $backup 'artifacts.zip';$manifestPath=Join-Path $backup 'backup-manifest.json'
function Resolve-DipPath([string]$Path,[string]$Root){if([IO.Path]::IsPathRooted($Path)){return [IO.Path]::GetFullPath($Path)};return [IO.Path]::GetFullPath((Join-Path $Root $Path))}
foreach($f in $dump,$zip,$manifestPath){if(-not(Test-Path $f -PathType Leaf)){throw "Backup component missing: $f"}}
$m=Get-Content $manifestPath -Raw|ConvertFrom-Json;if($m.schema-ne'dip-backup-v3'){throw "Native restore requires dip-backup-v3, found $($m.schema)."};if((Get-FileHash $dump -Algorithm SHA256).Hash-ne$m.databaseSha256){throw 'Database hash mismatch.'};if((Get-FileHash $zip -Algorithm SHA256).Hash-ne$m.artifactsSha256){throw 'Artifact hash mismatch.'}
$current=(& git -C $root rev-parse HEAD|Out-String).Trim();if(-not$AllowCrossRevisionRestore-and$m.sourceCommit-and$m.sourceCommit-ne$current){throw "Backup commit $($m.sourceCommit) differs from HEAD $current. Use -AllowCrossRevisionRestore only after compatibility review."}
$oldPg=$env:PGPASSWORD;$env:PGPASSWORD=$DatabasePassword;$safety=$null;$errorRecord=$null;$success=$false
try{
 & pg_restore --list $dump *> $null;if($LASTEXITCODE-ne0){throw 'Database archive validation failed.'}
 Add-Type -AssemblyName System.IO.Compression.FileSystem;$testDir=Join-Path ([IO.Path]::GetTempPath()) ('dip-restore-check-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $testDir|Out-Null;try{[IO.Compression.ZipFile]::ExtractToDirectory($zip,$testDir)}finally{Remove-Item $testDir -Recurse -Force -ErrorAction SilentlyContinue}
 if(-not$SkipSafetyBackup){$safety=@(& (Join-Path $PSScriptRoot 'Backup-Dip.ps1') -OutputDirectory 'artifacts\pre-restore-backups' -ArtifactDirectory $ArtifactDirectory -Database $Database -DatabaseUser $DatabaseUser -DatabaseHost $DatabaseHost -DatabasePort $DatabasePort -DatabasePassword $DatabasePassword)|Select-Object -Last 1}
 & (Join-Path $PSScriptRoot 'Stop-DIP.ps1') -KeepData
 $safeDb=$Database.Replace('"','""');$safeUser=$DatabaseUser.Replace('"','""')
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='$($Database.Replace("'","''"))' AND pid<>pg_backend_pid();" *> $null
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "DROP DATABASE IF EXISTS \"$safeDb\";" *> $null;if($LASTEXITCODE-ne0){throw 'Could not drop restore target database.'}
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"$safeDb\" OWNER \"$safeUser\";" *> $null;if($LASTEXITCODE-ne0){throw 'Could not create restore target database.'}
 & pg_restore -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $Database --clean --if-exists --no-owner --no-privileges $dump;if($LASTEXITCODE-ne0){throw 'Database restore failed.'}
 $artifactRoot=Resolve-DipPath $ArtifactDirectory $root;$stage="$artifactRoot.restore-$([guid]::NewGuid().ToString('N'))";New-Item -Force -ItemType Directory $stage|Out-Null;[IO.Compression.ZipFile]::ExtractToDirectory($zip,$stage);if(Test-Path $artifactRoot){$old="$artifactRoot.old-$([guid]::NewGuid().ToString('N'))";Move-Item $artifactRoot $old;Move-Item $stage $artifactRoot;Remove-Item $old -Recurse -Force}else{Move-Item $stage $artifactRoot}
 $count=(& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $Database -At -v ON_ERROR_STOP=1 -c 'SELECT count(*) FROM "__EFMigrationsHistory";'|Out-String).Trim();if($count-notmatch'^\d+$'-or[int]$count-lt1){throw 'EF migration history validation failed.'}
 & (Join-Path $PSScriptRoot 'Start-DIP.ps1') -NoBuild -NoBrowser;$success=$true;Write-Host "Restore completed: $backup" -ForegroundColor Green
}catch{$errorRecord=$_}finally{$env:PGPASSWORD=$oldPg}
if(-not$success){if($safety-and-not$DisableAutomaticRollback){Write-Warning "Restore failed; rolling back from $safety";& $PSCommandPath -BackupDirectory $safety -ConfirmRestore -SkipSafetyBackup -AllowCrossRevisionRestore -DisableAutomaticRollback -ArtifactDirectory $ArtifactDirectory -Database $Database -DatabaseUser $DatabaseUser -DatabaseHost $DatabaseHost -DatabasePort $DatabasePort -DatabasePassword $DatabasePassword};if($errorRecord){throw $errorRecord};throw 'Restore failed.'}
